#!/usr/bin/env python3
"""The lit model classes' title shaders (src/render/shaders/*.hlsl, generated by tools/shader_hlsl.py) -> GLSL
of our own for the Vulkan back end (engine improvements 2.1, docs/developers/own-engine-host.md).

The translation is exact (same operations in the same order) plus what per-pixel lighting needs:
- vertex programs also output the world position (location 11) and world normal (location 12), from the
  object-space point the program feeds to its matrix (the dot with c6) and the normal it lights (the dot with
  c10), through our object-to-world rows (vertex constants kGfxVsOwn + 1..3, own_model.glsl);
- pixel shaders take their diffuse colour from own_model_v0(v0) (own_model.glsl: the title's per-vertex sum, or
  ours per pixel with the sun's shadow) and end in own_model_out (debug views).

Output: src/render/vk/shaders/model_vs_KEY[_VARIANT].vert, model_ps_KEY.frag (generated, do not edit) and
model_shaders.csv (vertex key, variant, pixel keys of the same class).

usage: tools/shader_glsl.py [--check]   (--check: fail if the committed files differ)
"""

import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
HLSL = ROOT / "src/render/shaders"
OUT = ROOT / "src/render/vk/shaders"

# The classes lit by the four object lights (constants 10..17: directions, colour rows, ambient) whose lighting
# is the plain sum max(N.L, 0) x colour + ambient. cdAirplaneMetal lights with -c10 (a different model): left out.
CLASSES = ["cdGunSight", "cdGun", "cdPropeller", "cdChar", "cdSimpleUVAnim", "cdSimple"]

# The world classes' main draws (not their dynamic-light passes, InitVertexShaders2 / InitPixelShaders2): vertex
# programs [0] plain and [1] projected, pixel shaders by (projected + lightmap * 2) with the stages' roles:
# (lightmap stage or None, projector stage or None).
WORLD_VS = ["0089fa60", "0089fb28", "0089ea20", "0089eaf8"]
WORLD_PS = {
    "008a00a0": (None, None), "008a0190": (None, 1), "008a0280": (1, None), "008a0370": (1, 2),  # cdWorld
    "0089f090": (None, None), "0089f180": (None, 3), "0089f270": (2, None), "0089f360": (2, 3),  # cdWorldBlend
}

# The level's dynamic-light passes (2.5; additive, the dynamic-light falloff texture, one or two lights in c18 c19):
# vertex programs with the light count, pixel shaders.
WORLD_LIGHT_VS = {"0089fc58": 1, "0089fde0": 2, "0089ec48": 1, "0089edd0": 2}
WORLD_LIGHT_PS = {"008a0470": 1, "008a0560": 2, "0089f460": 1, "0089f550": 2}

HEADER = "// Generated by tools/shader_glsl.py from src/render/shaders/{src}; do not edit.\n"


def manifest():
    rows = []
    for line in (HLSL / "manifest.csv").read_text().splitlines()[1:]:
        stage, key, used = line.split(",", 2)
        cls = used.split("_")[0]
        rows.append((stage, key, cls))
    return rows


def common_expr(text):
    """HLSL expression syntax -> GLSL (the generated files' subset)."""
    text = re.sub(r"\(float4\)\(", "vec4(", text)
    # SGE / SLT: float4(a >= b) / float4(a < b) as component-wise compares
    text = re.sub(r"float4\(([\w.\[\]+ -]+?) >= ([\w.\[\]+ -]+?)\)", r"vec4(greaterThanEqual(\1, \2))", text)
    text = re.sub(r"float4\(([\w.\[\]+ -]+?) < ([\w.\[\]+ -]+?)\)", r"vec4(lessThan(\1, \2))", text)
    text = text.replace("float4(", "vec4(").replace("float3(", "vec3(").replace("float2(", "vec2(")
    text = re.sub(r"\(int\)floor\(", "int(floor(", text)
    # (int)floor(x) -> int(floor(x)): one more closing parenthesis after floor's
    text = re.sub(r"int\(floor\((\([^;]*?\)\.x)\)", r"int(floor(\1))", text)
    text = text.replace("rsqrt(", "inversesqrt(").replace("lerp(", "mix(").replace("frac(", "fract(")
    return text


def translate_vs(path, key, variant, world=False, lights=0):
    matrix_row = 7 if world else 6
    src = path.read_text().splitlines()
    out = [HEADER.format(src=path.name), "#version 450", "#extension GL_GOOGLE_include_directive : require",
           "#define OWN_VERTEX", '#include "own_model.glsl"', ""]
    if world:
        out.insert(3, "#define OWN_WORLD")
    if lights:
        out.insert(4, "#define OWN_DLIGHT")
    body = []
    inputs = []
    in_main = False
    pos_expr = normal_expr = None
    for line in src:
        s = line.strip()
        if s.startswith("//") or s.startswith("#") or not s:
            if in_main and s.startswith("//"):
                body.append(line)
            continue
        m = re.match(r"VsOut main\((.*)\) \{", s)
        if m:
            for arg in m.group(1).split(","):
                am = re.match(r"float4 v(\d+) : TEXCOORD(\d+)", arg.strip())
                inputs.append(int(am.group(1)))
            in_main = True
            continue
        if not in_main:
            continue
        if s == "}":
            break
        line = common_expr(line)
        line = re.sub(r"^(\s*)float4 ", r"\1vec4 ", line)
        if line.lstrip().startswith("vec4 "):
            line = re.sub(r"(\w+) = 0([,;])", r"\1 = vec4(0)\2", line)
        line = re.sub(r"^(\s*)(mac|ilu) = (.*);$", r"\1\2 = vec4(\3);", line)
        pm = re.search(r"dot\(([^;]*?), c\[%d\]\)" % matrix_row, line)
        if pm:
            body.append(f"    own_obj_pos = ({pm.group(1)}).xyz;")
            pos_expr = pm.group(1)
        nm = re.search(r"dot\(\((\w+)\.xyzz\)\.xyz, \(c\[10\]\.xyzz\)\.xyz\)", line)
        if nm:
            body.append(f"    own_obj_normal = {nm.group(1)}.xyz;")
            normal_expr = nm.group(1)
        rm = re.match(r"\s*return nv_epilogue\((.*)\);", line)
        if rm:
            body.append("    own_model_world(own_obj_pos, own_obj_normal);")
            body.append(f"    nv_epilogue({rm.group(1)});")
            continue
        body.append(line)
    if pos_expr is None or (normal_expr is None and not world):
        raise SystemExit(f"{path.name}: no position (c6) or normal (c10) dot found")
    for n in inputs:
        out.append(f"layout(location = {n}) in vec4 in_v{n};")
    if lights:
        # the surface's own texture coordinates (layer 0 in v1, cdWorldBlend's layer 1 in v2) for its normal maps
        for n in (1, 2):
            if n not in inputs:
                out.append(f"layout(location = {n}) in vec4 in_v{n};")
        body.insert(0, "    o_base_uv = vec4(in_v1.xy, in_v2.xy);")
    out.append("")
    out.append("void main() {")
    for n in inputs:
        out.append(f"    vec4 v{n} = in_v{n};")
    out.append("    vec3 own_obj_pos = vec3(0), own_obj_normal = vec3(0, 0, 1);")
    out.extend(body)
    out.append("}")
    return "\n".join(out) + "\n"


def translate_ps(path, world=None, lights=0):
    src = path.read_text().splitlines()
    out = [HEADER.format(src=path.name), "#version 450", "#extension GL_GOOGLE_include_directive : require",
           "#define OWN_PIXEL", '#include "own_model.glsl"', ""]
    lightmap, projector = world if world else (None, None)
    if lights:
        out.insert(3, "#define OWN_DLIGHT")
        if lights == 2:
            out.insert(4, "#define OWN_DLIGHT2")
    if world:
        out.insert(3, "#define OWN_WORLD")
        if path.name in ("ps_0089f090.hlsl", "ps_0089f180.hlsl", "ps_0089f270.hlsl", "ps_0089f360.hlsl"):
            out.insert(4, "#define OWN_WORLD_BLEND")
    body = []
    in_main = False
    for line in src:
        s = line.strip()
        if s.startswith("sampler2D"):
            continue
        if s.startswith("float4 main("):
            in_main = True
            continue
        if not in_main or s.startswith("float4 t2") or s.startswith("#"):
            continue
        if s == "}":
            break
        line = common_expr(line)
        if lights:
            line = line.replace("float4 V0 = v0, V1 = v1;", "vec4 V0 = v0, V1 = v1;\n    own_dlight_begin(V0, V1);")
        elif world:
            line = line.replace("float4 V0 = v0, V1 = v1;", "vec4 V0 = v0, V1 = v1;\n    own_world_begin();")
        else:
            line = line.replace("float4 V0 = v0, V1 = v1;", "vec4 V0 = own_model_v0(v0), V1 = v1;")
        if projector is not None and re.match(rf"\s*T{projector} = tex2Dproj\(s{projector}, ", line):
            # the projector's silhouette -> our depth compare's lost share in alpha (the combiners darken by it)
            line = f"    T{projector} = vec4(0.0, 0.0, 0.0, own_world_shadow(t{projector}));"
            body.append(line)
            continue
        line = re.sub(r"tex2Dproj\(s(\d), ", r"own_tex2Dproj_\1(", line)
        if lightmap is not None and re.match(rf"\s*T{lightmap} = own_tex2Dproj_{lightmap}\(", line):
            body.append(line)
            body.append(f"    T{lightmap}.rgb = own_world_light(T{lightmap}.rgb);")
            continue
        line = re.sub(r"^(\s*)float4 ", r"\1vec4 ", line)
        if line.lstrip().startswith("vec4 "):
            line = re.sub(r"(\w+) = 0([,;])", r"\1 = vec4(0)\2", line)
        rm = re.match(r"(\s*)return (.*);", line)
        if rm:
            body.append(f"{rm.group(1)}own_model_out({rm.group(2)});")
            continue
        body.append(line)
    if not world and not any("own_model_v0" in b for b in body):
        raise SystemExit(f"{path.name}: no V0 line")
    return "\n".join(out + ["void main() {"] + body + ["}"]) + "\n"


def main():
    check = "--check" in sys.argv
    rows = manifest()
    files = {}
    table = ["vertex,variant,pixel"]
    for cls in CLASSES:
        vs = [k for st, k, c in rows if st == "vs" and c == cls]
        ps = [k for st, k, c in rows if st == "ps" and c == cls]
        for k in vs:
            key, _, variant = k.partition("_")
            files[f"model_vs_{k}.vert"] = translate_vs(HLSL / f"vs_{k}.hlsl", key, variant)
            table.append(f"{key},{variant or 0},{' '.join(ps)}")
        for k in ps:
            files[f"model_ps_{k}.frag"] = translate_ps(HLSL / f"ps_{k}.hlsl")
    for k in sorted(p.stem[3:] for p in HLSL.glob("vs_*.hlsl")):
        if k.split("_")[0] in WORLD_VS:
            key, _, variant = k.partition("_")
            files[f"model_vs_{k}.vert"] = translate_vs(HLSL / f"vs_{k}.hlsl", key, variant, world=True)
            table.append(f"{key},{variant or 0},world")
    for k, roles in WORLD_PS.items():
        files[f"model_ps_{k}.frag"] = translate_ps(HLSL / f"ps_{k}.hlsl", roles)
    for k in sorted(p.stem[3:] for p in HLSL.glob("vs_*.hlsl")):
        if k.split("_")[0] in WORLD_LIGHT_VS:
            key, _, variant = k.partition("_")
            files[f"model_vs_{k}.vert"] = translate_vs(HLSL / f"vs_{k}.hlsl", key, variant, world=True,
                                                       lights=WORLD_LIGHT_VS[key])
            table.append(f"{key},{variant or 0},world-light")
    for k, n in WORLD_LIGHT_PS.items():
        files[f"model_ps_{k}.frag"] = translate_ps(HLSL / f"ps_{k}.hlsl", (None, None), lights=n)
    files["model_shaders.csv"] = "\n".join(table) + "\n"
    stale = False
    for name, text in files.items():
        path = OUT / name
        if check:
            if not path.exists() or path.read_text() != text:
                print(f"stale: {path}")
                stale = True
        else:
            path.write_text(text)
    if not check:
        for old in OUT.glob("model_*"):
            if old.name not in files:
                old.unlink()
        print(f"{len(files)} files -> {OUT}")
    sys.exit(1 if stale else 0)


if __name__ == "__main__":
    main()
